const x = $input.first().json;

const text = v => String(v ?? '').trim();

const optionalNumber = (v, max) => {
  if (
    v === '' ||
    v === null ||
    v === undefined ||
    v === 0 ||
    v === '0'
  ) {
    return null;
  }

  const n = Number(v);

  if (!Number.isFinite(n) || n <= 0 || n > max) {
    throw new Error(
      'Budget/timeline must be a positive number within the allowed range.'
    );
  }

  return n;
};

const email = text(x.email).toLowerCase();

if (
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ||
  email.length > 254
) {
  throw new Error('Invalid email');
}

const full_name = text(x.full_name).slice(0, 120);
const company = text(x.company).slice(0, 120);
const requirement = text(x.requirement);

if (
  !full_name ||
  !company ||
  requirement.length < 10 ||
  requirement.length > 5000
) {
  throw new Error(
    'Name/company required; requirement must contain 10–5000 characters.'
  );
}

const project_ref = text(x.project_ref).toUpperCase();

if (!/^[A-Z0-9_-]{3,40}$/.test(project_ref)) {
  throw new Error(
    'Project reference: 3–40 letters, digits, hyphen or underscore.'
  );
}

const raw = text(x.website).toLowerCase();

if (!raw || /\s/.test(raw)) {
  throw new Error('Invalid website');
}

const domain = raw
  .replace(/^https?:\/\//, '')
  .split(/[/?#]/)[0]
  .replace(/^www\./, '')
  .replace(/\.$/, '');

if (
  !/^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain)
) {
  throw new Error(
    'Enter a valid business website domain, e.g. example.com'
  );
}

const allowed = [
  'Website',
  'Marketing',
  'Automation',
  'Not sure'
];

const service = text(x.service);

if (!allowed.includes(service)) {
  throw new Error('Unknown service');
}

const phone = text(x.phone).slice(0, 40);

const budget_usd = optionalNumber(
  x.budget_usd,
  10000000
);

const timeline_days = optionalNumber(
  x.timeline_days,
  3650
);

const opportunity_key = `${email}|${project_ref}`;

const submission_key = JSON.stringify({
  full_name,
  email,
  phone,
  company,
  domain,
  project_ref,
  service,
  budget_usd,
  timeline_days,
  requirement
});

return [{
  json: {
    ...x,
    full_name,
    email,
    phone,
    company,
    domain,
    website: `https://${domain}`,
    project_ref,
    service,
    budget_usd,
    timeline_days,
    requirement,
    opportunity_key,
    submission_key,
    received_at: $now.toISO()
  }
}];

const lead = $('Normalize Lead').first().json;

let a = $input.first().json;
a = a.output ?? a.text ?? a;

if (typeof a === 'string') {
  a = JSON.parse(a);
}

if (
  !a ||
  typeof a !== 'object' ||
  Array.isArray(a)
) {
  throw new Error('Invalid AI output');
}

if (
  !['supported', 'unrelated', 'unclear']
    .includes(a.service_fit)
) {
  throw new Error('Invalid service fit');
}

if (
  !['Website', 'Marketing', 'Automation', 'Unknown']
    .includes(a.service)
) {
  throw new Error('Invalid AI service');
}

if (
  typeof a.summary !== 'string' ||
  typeof a.evidence !== 'string' ||
  !Array.isArray(a.missing_questions)
) {
  throw new Error('Incomplete AI output');
}

const service =
  lead.service === 'Not sure'
    ? a.service
    : lead.service;

const fit =
  a.service_fit === 'supported' &&
  service !== 'Unknown';

const missing = [];

if (lead.budget_usd === null) {
  missing.push(
    'What budget range have you allocated in USD?'
  );
}

if (lead.timeline_days === null) {
  missing.push(
    'When would you like the project to start?'
  );
}

if (
  service === 'Unknown' ||
  a.service_fit === 'unclear'
) {
  missing.push(
    'Which service and specific outcome do you need?'
  );
}

const questions = [...new Set([
  ...missing,
  ...a.missing_questions
    .filter(q => typeof q === 'string')
    .map(q => q.slice(0, 200))
])].slice(0, 5);

let score = fit ? 40 : 0;

if (lead.budget_usd !== null) {
  score += lead.budget_usd >= 1000 ? 30 : 15;
}

if (lead.timeline_days !== null) {
  score += lead.timeline_days <= 30 ? 20 : 10;
}

if (lead.requirement.length >= 40) {
  score += 10;
}

let rating;

if (a.service_fit === 'unrelated') {
  rating = 'Not Fit';
} else if (
  !fit ||
  missing.length ||
  a.missing_questions.length
) {
  rating = 'Need Details';
} else {
  rating = score >= 80 ? 'Hot' : 'Warm';
}

const owner =
  service === 'Marketing'
    ? lead.owner_marketing
    : service === 'Automation'
      ? lead.owner_automation
      : lead.owner_website;

if (!/^\d+$/.test(String(owner))) {
  throw new Error('Replace owner ID placeholder');
}

const due =
  rating === 'Hot'
    ? $now.plus({ hours: 1 })
    : rating === 'Warm'
      ? $now.plus({ hours: 24 })
      : $now.plus({ hours: 48 });

const stage =
  ['Hot', 'Warm'].includes(rating)
    ? lead.stage_qualified
    : lead.stage_new;

const description = [
  `Rating: ${rating} | Score: ${score}/100`,
  `Service: ${service}`,
  `Project reference: ${lead.project_ref}`,
  `Customer budget USD: ${lead.budget_usd ?? 'Not supplied'}`,
  `Desired start in days: ${lead.timeline_days ?? 'Not supplied'}`,
  `Summary: ${a.summary.slice(0, 1000)}`,
  `Fit evidence: ${a.evidence.slice(0, 500)}`,
  `Clarifications: ${questions.join(' | ') || 'None'}`,
  `Original inquiry: ${lead.requirement}`,
  `Received: ${lead.received_at}`
].join('\n');

return [{
  json: {
    ...lead,
    ai: a,
    resolved_service: service,
    rating,
    score,
    owner_id: String(owner),
    due_at: due.toUTC().toISO(),
    initial_stage: stage,
    questions,
    description,
    deal_name:
      `${lead.company} - ${service} - ${lead.project_ref}`
  }
}];

const r = $input.first().json;
const l = $('Qualify Lead').first().json;

if (![200, 404].includes(Number(r.statusCode))) {
  throw new Error(
    `Contact lookup failed: ${r.statusCode}`
  );
}

const existing = Number(r.statusCode) === 200;

const parts = l.full_name.split(/\s+/);

const properties = {
  email: l.email,
  firstname: parts[0],
  company: l.company,
  website: l.website
};

if (parts.length > 1) {
  properties.lastname = parts.slice(1).join(' ');
}

if (l.phone) {
  properties.phone = l.phone;
}

if (!r.body?.properties?.hubspot_owner_id) {
  properties.hubspot_owner_id = l.owner_id;
}

return [{
  json: {
    method: existing ? 'PATCH' : 'POST',
    url:
      'https://api.hubapi.com/crm/v3/objects/contacts' +
      (existing ? '/' + r.body.id : ''),
    payload: {
      properties
    }
  }
}];

