const r = $input.first().json.body;
const l = $('Qualify Lead').first().json;

if (!r || !Array.isArray(r.results)) {
  throw new Error('Invalid company search response');
}

if (
  Number(r.total) > 1 ||
  r.results.length > 1
) {
  throw new Error(
    'Multiple companies match this domain. Review/merge manually.'
  );
}

const old = r.results[0];

return [{
  json: {
    method: old ? 'PATCH' : 'POST',
    url:
      'https://api.hubapi.com/crm/v3/objects/companies' +
      (old ? '/' + old.id : ''),
    payload: {
      properties: {
        name: l.company,
        domain: l.domain,
        aa_domain_key: l.domain
      }
    }
  }
}];

const r = $input.first().json;
const l = $('Qualify Lead').first().json;

if (![200, 404].includes(Number(r.statusCode))) {
  throw new Error(
    `Deal lookup failed: ${r.statusCode}`
  );
}

let parsed = r.body ?? r.data;
if (typeof parsed === 'string') {
  try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; }
}

const old =
  Number(r.statusCode) === 200
    ? parsed
    : null;

const p = old?.properties ?? {};

const duplicate =
  p.aa_submission_key === l.submission_key;

const closed = [
  l.stage_won,
  l.stage_lost
].includes(p.dealstage);

if (old && p.pipeline !== l.pipeline_id) {
  throw new Error(
    'Deal belongs to another pipeline. Review manually.'
  );
}

let stage =
  old ? p.dealstage : l.initial_stage;

if (
  old &&
  p.dealstage === l.stage_new &&
  l.initial_stage === l.stage_qualified
) {
  stage = l.stage_qualified;
}

const owner =
  p.hubspot_owner_id || l.owner_id;

const properties = {
  dealname: l.deal_name,
  description: l.description,
  aa_opportunity_key: l.opportunity_key,
  aa_rating: l.rating,
  aa_score: String(l.score),
  aa_service: l.resolved_service,
  hubspot_owner_id: owner,
  dealstage: stage
};

if (!old) {
  properties.pipeline = l.pipeline_id;
}

return [{
  json: {
    proceed: !duplicate && !closed,
    duplicate,
    closed,
    reason: duplicate
      ? 'Same inquiry already completed'
      : closed
        ? 'Closed deal: use a new project reference for new work'
        : 'Proceed',
    owner_id: owner,
    method: old ? 'PATCH' : 'POST',
    url:
      'https://api.hubapi.com/crm/v3/objects/deals' +
      (old ? '/' + old.id : ''),
    payload: {
      properties
    }
  }
}];

