const r = $input.first().json.body;

if (!r || !Array.isArray(r.results)) {
  throw new Error('Invalid task search');
}

if (
  Number(r.total) > 1 ||
  r.results.length > 1
) {
  throw new Error(
    'Duplicate CRM tasks require review'
  );
}

const old = r.results[0];
const l = $('Qualify Lead').first().json;
const dealId = $('Save Deal').first().json.body.id;

const properties = {
  hs_task_subject:
    `CRM qualification | deal ${dealId}`,

  hs_task_body: l.description,

  hs_task_priority:
    l.rating === 'Hot'
      ? 'HIGH'
      : l.rating === 'Warm'
        ? 'MEDIUM'
        : 'LOW',

  hubspot_owner_id:
    $('Deal Decision').first().json.owner_id,

  hs_task_type: 'TODO'
};

if (!old) {
  properties.hs_timestamp = l.due_at;
  properties.hs_task_status = 'NOT_STARTED';
}

return [{
  json: {
    method: old ? 'PATCH' : 'POST',
    url:
      'https://api.hubapi.com/crm/v3/objects/tasks' +
      (old ? '/' + old.id : ''),
    payload: {
      properties
    }
  }
}];

const l = $('Qualify Lead').first().json;
const id = $('Save Deal').first().json.body.id;
const first = l.full_name.split(/\s+/)[0];

let main;

if (l.rating === 'Not Fit') {
  main =
    'Thank you for your inquiry. Our team will review ' +
    'whether your request is within our service scope ' +
    'and advise you on the next step.';
} else if (l.rating === 'Need Details') {
  const qs = l.questions.length
    ? l.questions
    : ['Could you clarify the exact outcome you need?'];

  main =
    'Thank you for sharing your project. ' +
    'To review it properly, could you please confirm:\n\n' +
    qs.map((q, i) => `${i + 1}. ${q}`).join('\n');
} else {
  main =
    `Thank you for sharing your ` +
    `${l.resolved_service.toLowerCase()} requirement. ` +
    'Our team will review the scope and contact you ' +
    'to arrange a suitable discovery call. ' +
    'Please share any examples or must-have features ' +
    'that would help us prepare.';
}

return [{
  json: {
    to: l.email,
    subject:
      `Your project inquiry - ${l.project_ref} ` +
      `[CRMREF_${id}]`,
    body:
      `Hi ${first},\n\n${main}\n\n` +
      'Best regards,\nHaroon AI Automation'
  }
}];
